/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const rows = JSON.parse(readFileSync('./work/rows.json', 'utf8'));
const amountsToDto = (amount) => ({ unit: 'EUR-cent', value: amount.toString() });

const settlement = rows.map(({ id, unitMinor, quantity, kind }) => {
  assert.ok(Number.isSafeInteger(quantity), 'quantity must be an exact integer');
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, 'floor');
  if (kind === 'standard') {
    return {
      id,
      status: 'calculated',
      net: amountsToDto(net),
      fee: amountsToDto(mulDivMinor(net, 1n, 10n, 'floor')),
    };
  }
  assert.equal(kind, 'manual');
  return {
    id,
    status: 'blocked',
    net: amountsToDto(net),
    fee: null,
    decisionRequired: 'Марина, владелец расчётов, должна утвердить ставку сбора и правило округления для manual.',
  };
});

writeFileSync('./settlement.json', JSON.stringify(settlement, null, 2) + '\\n', { flag: 'wx' });
NODE
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { readMinor } from './work/lib/money.mjs';

const rows = JSON.parse(readFileSync('./work/rows.json', 'utf8'));
const result = JSON.parse(readFileSync('./settlement.json', 'utf8'));
assert.deepEqual(result.map(({ id }) => id), rows.map(({ id }) => id));
function parseDto(dto) {
  assert.deepEqual(Object.keys(dto).sort(), ['unit', 'value']);
  assert.equal(dto.unit, 'EUR-cent');
  return readMinor(dto.value);
}
assert.deepEqual(
  result.map(({ id, status, net, fee }) => [id, status, parseDto(net), fee === null ? null : parseDto(fee)]),
  [
    ['CR', 'calculated', -3n, -1n],
    ['CS', 'calculated', 38n, 3n],
    ['CT', 'blocked', 22n, null],
  ],
);
assert.match(result[2].decisionRequired, /Марина.*ставку.*округления/);
console.log('Verified row coverage, EUR-cent DTOs, expected results and pending decision.');
NODE
cat settlement.json"

